do $curate$ declare bid uuid; begin if exists(select 1 from public.businesses where lower(name)=lower('JT Landscape Management') or regexp_replace(coalesce(phone,''),'[^0-9]','','g') ~ '2093989279$' or lower(rtrim(website,'/'))=lower(rtrim('https://jtlandscapemgt.com/','/'))) then raise exception 'Duplicate candidate requires review'; end if; insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('JT Landscape Management','Home Services','Turlock','','(209) 398-9279','https://jtlandscapemgt.com/','Turlock-based landscape construction business advertising service in Tracy, Manteca and Lathrop. Services include yard remodels, pavers, turf, sod, retaining walls and irrigation. Mountain House project photos appear on the website, but current Mountain House coverage was not established in its service-area list. Confirm project scope and availability directly.','approved',true,false,null,0,'editorial_first_party','https://jtlandscapemgt.com/','first_party_website_desk_check',now()) returning id into bid; insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name": "JT Landscape Management", "city": "Turlock", "address": "", "phone": "(209) 398-9279", "website": "https://jtlandscapemgt.com/", "description": "Turlock-based landscape construction business advertising service in Tracy, Manteca and Lathrop. Services include yard remodels, pavers, turf, sod, retaining walls and irrigation. Mountain House project photos appear on the website, but current Mountain House coverage was not established in its service-area list. Confirm project scope and availability directly.", "tags": ["landscaping", "landscape construction", "pavers", "irrigation", "artificial turf"], "areas": ["Tracy", "Lathrop", "Manteca"], "note": "Primary contact/about pages explicitly list service cities, Turlock base and public phone. Homepage has Mountain House project captions; historical work alone is not current coverage. Stock review photos, testimonials, prices, license and insurance claims not adopted. Sources https://jtlandscapemgt.com/contact and /about."}'::jsonb,'Individually sourced relaunch addition; primary-site desk check only','https://jtlandscapemgt.com/'); insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://jtlandscapemgt.com/',array['identity','public phone','website','advertised services','advertised service area'],array['Tracy','Lathrop','Manteca'],array['landscaping','landscape construction','pavers','irrigation','artificial turf'],'First-party website desk check only. No owner confirmation, credential validation, availability check or quality endorsement. Primary contact/about pages explicitly list service cities, Turlock base and public phone. Homepage has Mountain House project captions; historical work alone is not current coverage. Stock review photos, testimonials, prices, license and insurance claims not adopted. Sources https://jtlandscapemgt.com/contact and /about.'); end $curate$;
do $curate$ declare bid uuid; begin if exists(select 1 from public.businesses where lower(name)=lower('Golden Valley Materials Inc.') or regexp_replace(coalesce(phone,''),'[^0-9]','','g') ~ '2098300280$' or lower(rtrim(website,'/'))=lower(rtrim('https://goldenvalleymaterials.com/','/'))) then raise exception 'Duplicate candidate requires review'; end if; insert into public.businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('Golden Valley Materials Inc.','Home Services','Tracy','26701 S. Lammers Rd., Tracy, CA 95377','(209) 830-0280','https://goldenvalleymaterials.com/','Landscape and hardscape materials supplier with a public yard in Tracy. Advertises rocks, gravel, pavers, soil, mulch, sod, concrete and equipment rental, with delivery coverage naming Mountain House, Tracy, Lathrop and Manteca. Confirm stock, delivery timing and rental availability directly. This is a materials supplier; landscape installation services were not established.','approved',true,false,null,0,'editorial_first_party','https://goldenvalleymaterials.com/','first_party_website_desk_check',now()) returning id into bid; insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}'::jsonb,'{"name": "Golden Valley Materials Inc.", "city": "Tracy", "address": "26701 S. Lammers Rd., Tracy, CA 95377", "phone": "(209) 830-0280", "website": "https://goldenvalleymaterials.com/", "description": "Landscape and hardscape materials supplier with a public yard in Tracy. Advertises rocks, gravel, pavers, soil, mulch, sod, concrete and equipment rental, with delivery coverage naming Mountain House, Tracy, Lathrop and Manteca. Confirm stock, delivery timing and rental availability directly. This is a materials supplier; landscape installation services were not established.", "tags": ["landscape supplies", "garden supplies", "pavers", "equipment rental"], "areas": ["Mountain House", "Tracy", "Lathrop", "Manteca"], "note": "Primary website confirms public yard, phone, product types and named delivery cities. Not tagged as a landscaping installer. Same-day promises, prices, ratings, licensing and DOT claims not adopted."}'::jsonb,'Individually sourced relaunch addition; primary-site desk check only','https://goldenvalleymaterials.com/'); insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://goldenvalleymaterials.com/',array['identity','public phone','website','advertised services','advertised service area'],array['Mountain House','Tracy','Lathrop','Manteca'],array['landscape supplies','garden supplies','pavers','equipment rental'],'First-party website desk check only. No owner confirmation, credential validation, availability check or quality endorsement. Primary website confirms public yard, phone, product types and named delivery cities. Not tagged as a landscaping installer. Same-day promises, prices, ratings, licensing and DOT claims not adopted.'); end $curate$;
